#include "cliplogic.h"

#include <QCryptographicHash>
#include <QFileInfo>
#include <QStringDecoder>
#include <QUrl>

#include <algorithm>

namespace ClipLogic
{
const char kMarkerType[] = "application/x-grassfield-clipboard-item";

namespace
{
// Compared after normalizeType(). Presence is enough: the value of x-kde-passwordManagerHint is never read (ADR-0034 §1b).
const QList<QByteArray> kSecretTypes = {"x-kde-passwordmanagerhint", "org.nspasteboard.concealedtype",
                                        "org.nspasteboard.transienttype", "org.nspasteboard.autogeneratedtype"};
const QList<QByteArray> kPlainPriority = {"text/plain;charset=utf-8", "utf8_string", "text/plain", "string", "text"};
const QList<QByteArray> kImagePriority = {"image/png", "image/jpeg", "image/webp"};

bool isLatin1Type(const QByteArray &type)
{
    const QByteArray n = normalizeType(type);
    return n == "string" || n == "text";
}

// Characters a title or an excerpt never shows: C0 and C1 controls (but the excerpt's line breaks) and format characters
// (bidirectional overrides, zero-width marks), which could make one item look like another.
bool hidden(QChar c, bool keepNewline)
{
    if (keepNewline && c == QLatin1Char('\n'))
        return false;
    const QChar::Category cat = c.category();
    return cat == QChar::Other_Control || cat == QChar::Other_Format || c == QChar(0x2028) || c == QChar(0x2029);
}

QString cut(const QString &text, int chars)
{
    if (text.size() <= chars)
        return text;
    int n = chars;
    if (n > 0 && text.at(n - 1).isHighSurrogate())
        --n;
    return text.left(n);
}

bool decodeUtf8Strict(const QByteArray &data, QString *out)
{
    QStringDecoder decoder(QStringConverter::Utf8, QStringConverter::Flag::Stateless);
    QString text = decoder(data);
    if (decoder.hasError())
        return false;
    *out = text;
    return true;
}

bool decodeUtf16(const QByteArray &data, QStringConverter::Encoding encoding, QString *out)
{
    QStringDecoder decoder(encoding, QStringConverter::Flag::Stateless);
    QString text = decoder(data);
    if (decoder.hasError())
        return false;
    *out = text;
    return true;
}

QString entity(const QString &name, bool *known)
{
    *known = true;
    if (name == QLatin1String("amp"))
        return QStringLiteral("&");
    if (name == QLatin1String("lt"))
        return QStringLiteral("<");
    if (name == QLatin1String("gt"))
        return QStringLiteral(">");
    if (name == QLatin1String("quot"))
        return QStringLiteral("\"");
    if (name == QLatin1String("apos"))
        return QStringLiteral("'");
    if (name == QLatin1String("nbsp"))
        return QStringLiteral(" ");
    if (name.startsWith(QLatin1Char('#'))) {
        bool ok = false;
        const uint code = name.size() > 1 && (name.at(1) == QLatin1Char('x') || name.at(1) == QLatin1Char('X'))
            ? name.mid(2).toUInt(&ok, 16)
            : name.mid(1).toUInt(&ok, 10);
        if (ok && code > 0 && code <= 0x10FFFF && !(code >= 0xD800 && code <= 0xDFFF)) {
            const char32_t c = char32_t(code);
            return QString::fromUcs4(&c, 1);
        }
    }
    *known = false;
    return {};
}
} // namespace

QByteArray kindName(Kind kind)
{
    switch (kind) {
    case Kind::Text:
        return "text";
    case Kind::Image:
        return "image";
    case Kind::Files:
        return "files";
    case Kind::None:
        break;
    }
    return "none";
}

Kind kindFromName(const QByteArray &name)
{
    if (name == "text")
        return Kind::Text;
    if (name == "image")
        return Kind::Image;
    if (name == "files")
        return Kind::Files;
    return Kind::None;
}

QByteArray normalizeType(const QByteArray &type)
{
    QByteArray out;
    out.reserve(type.size());
    for (const char c : type) {
        if (c == ' ' || c == '\t')
            continue;
        out += (c >= 'A' && c <= 'Z') ? char(c - 'A' + 'a') : c;
    }
    return out;
}

QList<QByteArray> Plan::reads() const
{
    QList<QByteArray> out;
    switch (kind) {
    case Kind::Files:
        out << filesType;
        if (!plainType.isEmpty())
            out << plainType;
        break;
    case Kind::Image:
        out << imageType;
        break;
    case Kind::Text:
        for (const QByteArray &t : {plainType, htmlType, rtfType})
            if (!t.isEmpty())
                out << t;
        break;
    case Kind::None:
        break;
    }
    return out;
}

qint64 Plan::cap(const QByteArray &type) const
{
    if (type == filesType)
        return kFilesCap;
    if (type == imageType)
        return kImageCap;
    if (type == htmlType)
        return kHtmlCap;
    if (type == rtfType)
        return kRtfCap;
    return kPlainCap;
}

Plan plan(const QList<QByteArray> &types, bool tooMany)
{
    Plan p;
    if (tooMany || types.size() > kMaxTypes) {
        p.refusal = Refusal::TooManyTypes;
        return p;
    }
    QHash<QByteArray, QByteArray> offered; // normalized -> as offered (the first spelling)
    for (const QByteArray &t : types) {
        const QByteArray n = normalizeType(t);
        if (!offered.contains(n))
            offered.insert(n, t);
    }
    for (const QByteArray &s : kSecretTypes) {
        if (offered.contains(s)) {
            p.refusal = Refusal::Secret;
            return p;
        }
    }
    p.hasMarker = offered.contains(QByteArray(kMarkerType));
    for (const QByteArray &c : kPlainPriority) {
        if (offered.contains(c)) {
            p.plainType = offered.value(c);
            break;
        }
    }
    if (offered.contains("text/uri-list")) {
        p.kind = Kind::Files;
        p.refusal = Refusal::None;
        p.filesType = offered.value("text/uri-list");
        return p;
    }
    for (const QByteArray &c : kImagePriority) {
        if (offered.contains(c)) {
            p.kind = Kind::Image;
            p.refusal = Refusal::None;
            p.imageType = offered.value(c);
            p.plainType.clear();
            return p;
        }
    }
    if (offered.contains("text/html"))
        p.htmlType = offered.value("text/html");
    if (offered.contains("text/rtf"))
        p.rtfType = offered.value("text/rtf");
    else if (offered.contains("application/rtf"))
        p.rtfType = offered.value("application/rtf");
    if (!p.plainType.isEmpty() || !p.htmlType.isEmpty()) {
        p.kind = Kind::Text;
        p.refusal = Refusal::None;
        return p;
    }
    p.htmlType.clear();
    p.rtfType.clear();
    p.refusal = Refusal::Unsupported;
    return p;
}

qint64 Item::size() const
{
    qint64 n = plain.size();
    for (const Part &part : parts)
        n += part.data.size();
    return n;
}

bool Item::formatted() const
{
    return kind == Kind::Text && !parts.isEmpty();
}

bool decodePlain(const QByteArray &type, const QByteArray &data, QString *out)
{
    QByteArray bytes = data;
    while (bytes.endsWith('\0'))
        bytes.chop(1);
    if (isLatin1Type(type)) {
        *out = QString::fromLatin1(bytes);
        return true;
    }
    return decodeUtf8Strict(bytes, out);
}

QString stripHtml(const QByteArray &html, bool *ok)
{
    QString text;
    bool decoded = false;
    if (html.startsWith("\xff\xfe"))
        decoded = decodeUtf16(html.mid(2), QStringConverter::Utf16LE, &text);
    else if (html.startsWith("\xfe\xff"))
        decoded = decodeUtf16(html.mid(2), QStringConverter::Utf16BE, &text);
    else
        decoded = decodeUtf8Strict(html, &text);
    *ok = decoded;
    if (!decoded)
        return {};
    QString out;
    out.reserve(text.size());
    const qsizetype n = text.size();
    qsizetype i = 0;
    // One pass; every search starts where the previous one stopped, so the cost is linear in the input.
    while (i < n) {
        const QChar c = text.at(i);
        if (c == QLatin1Char('<')) {
            if (text.mid(i, 4) == QLatin1String("<!--")) {
                const qsizetype end = text.indexOf(QLatin1String("-->"), i + 4);
                i = end < 0 ? n : end + 3;
                continue;
            }
            const qsizetype close = text.indexOf(QLatin1Char('>'), i + 1);
            if (close < 0)
                break;
            qsizetype s = i + 1;
            const bool closing = s < close && text.at(s) == QLatin1Char('/');
            if (closing)
                ++s;
            qsizetype e = s;
            while (e < close && (text.at(e).isLetterOrNumber()))
                ++e;
            const QString name = text.mid(s, e - s).toLower();
            i = close + 1;
            if (!closing && (name == QLatin1String("script") || name == QLatin1String("style"))) {
                const qsizetype end = text.indexOf(QLatin1String("</") + name, i, Qt::CaseInsensitive);
                if (end < 0) {
                    i = n;
                    break;
                }
                const qsizetype gt = text.indexOf(QLatin1Char('>'), end);
                i = gt < 0 ? n : gt + 1;
                continue;
            }
            static const QStringList breaks = {QStringLiteral("br"), QStringLiteral("p"), QStringLiteral("div"),
                                               QStringLiteral("li"), QStringLiteral("tr"), QStringLiteral("h1"),
                                               QStringLiteral("h2"), QStringLiteral("h3"), QStringLiteral("h4"),
                                               QStringLiteral("h5"), QStringLiteral("h6")};
            if (breaks.contains(name) && (closing || name == QLatin1String("br")))
                out += QLatin1Char('\n');
            continue;
        }
        if (c == QLatin1Char('&')) {
            const qsizetype semi = text.indexOf(QLatin1Char(';'), i + 1);
            if (semi > i + 1 && semi - i <= 10) {
                bool known = false;
                const QString value = entity(text.mid(i + 1, semi - i - 1), &known);
                if (known) {
                    out += value;
                    i = semi + 1;
                    continue;
                }
            }
        }
        out += c;
        ++i;
    }
    return out.trimmed();
}

bool parseUriList(const QByteArray &data, QStringList *paths)
{
    QStringList out;
    for (QByteArray line : data.split('\n')) {
        if (line.endsWith('\r'))
            line.chop(1);
        line = line.trimmed();
        if (line.isEmpty() || line.startsWith('#'))
            continue;
        if (!normalizeType(line.left(7)).startsWith("file://"))
            return false;
        const QUrl url(QString::fromUtf8(line), QUrl::StrictMode);
        // file://host/path is another machine's file (Qt maps it to a UNC path): only an empty host or localhost is local.
        if (!url.isValid() || !url.isLocalFile() || !(url.host().isEmpty() || url.host() == QLatin1String("localhost")))
            return false;
        const QString path = url.toLocalFile();
        if (path.isEmpty() || !path.startsWith(QLatin1Char('/')))
            return false;
        out << path;
        if (out.size() > kMaxFiles)
            return false;
    }
    if (out.isEmpty())
        return false;
    *paths = out;
    return true;
}

QString titleOf(const QString &text)
{
    for (const QString &raw : text.split(QLatin1Char('\n'))) {
        QString line;
        line.reserve(raw.size());
        for (const QChar c : raw)
            line += c == QLatin1Char('\t') ? QLatin1Char(' ') : c;
        QString clean;
        clean.reserve(line.size());
        for (const QChar c : line)
            if (!hidden(c, false))
                clean += c;
        clean = clean.trimmed();
        if (!clean.isEmpty())
            return cut(clean, kTitleChars);
    }
    return {};
}

QString excerptOf(const QString &text)
{
    QString clean;
    const QString head = cut(text, kExcerptChars * 2);
    clean.reserve(head.size());
    for (const QChar c : head) {
        if (c == QLatin1Char('\t'))
            clean += QLatin1Char(' ');
        else if (!hidden(c, true))
            clean += c;
    }
    return cut(clean.trimmed(), kExcerptChars);
}

QString searchKey(const QString &text)
{
    const QString decomposed = text.normalized(QString::NormalizationForm_KD);
    QString out;
    out.reserve(decomposed.size());
    for (const QChar c : decomposed) {
        const QChar::Category cat = c.category();
        if (cat == QChar::Mark_NonSpacing || cat == QChar::Mark_SpacingCombining || cat == QChar::Mark_Enclosing)
            continue;
        out += c;
    }
    return out.toCaseFolded();
}

QByteArray hashOf(Kind kind, const QByteArray &data)
{
    QCryptographicHash hash(QCryptographicHash::Sha256);
    hash.addData(kindName(kind));
    hash.addData(QByteArrayView("\0", 1));
    hash.addData(data);
    return hash.result().toHex();
}

Built build(const Plan &plan, const QHash<QByteArray, ReadResult> &results)
{
    Built b;
    auto get = [&results](const QByteArray &type) -> const ReadResult * {
        const auto it = results.constFind(type);
        return it == results.cend() ? nullptr : &it.value();
    };
    auto fail = [&b](const char *why) {
        b.ok = false;
        b.error = why;
        return b;
    };
    Kind kind = plan.kind;
    if (kind == Kind::None)
        return fail("not a supported kind");
    if (kind == Kind::Files) {
        const ReadResult *r = get(plan.filesType);
        if (!r || r->status == ReadResult::Failed)
            return fail("the file list was not read");
        if (r->status == ReadResult::OverCap)
            return fail("the file list is over its limit");
        QStringList paths;
        if (parseUriList(r->data, &paths)) {
            Item &it = b.item;
            it.kind = Kind::Files;
            it.files = paths;
            it.plain = paths.join(QLatin1Char('\n'));
            it.parts = {{"text/uri-list", uriList(paths)}};
            QStringList names;
            for (const QString &p : paths)
                names << QFileInfo(p).fileName();
            it.title = titleOf(names.first());
            it.excerpt = excerptOf(names.join(QLatin1Char('\n')));
            it.hash = hashOf(Kind::Files, it.plain.toUtf8());
            b.ok = true;
            return b;
        }
        if (plan.plainType.isEmpty())
            return fail("not a list of local files");
        kind = Kind::Text; // a list of links: its plain text
    }
    if (kind == Kind::Image) {
        const ReadResult *r = get(plan.imageType);
        if (!r || r->status == ReadResult::Failed || r->data.isEmpty())
            return fail("the image was not read");
        if (r->status == ReadResult::OverCap)
            return fail("the image is over its limit");
        Item &it = b.item;
        it.kind = Kind::Image;
        const QByteArray mime = normalizeType(plan.imageType);
        it.parts = {{mime, r->data}};
        it.imageFormat = mime == "image/png" ? "png" : mime == "image/jpeg" ? "jpeg" : "webp";
        it.hash = hashOf(Kind::Image, r->data);
        b.ok = true;
        return b;
    }
    // Text.
    QString plain;
    const ReadResult *pr = plan.plainType.isEmpty() ? nullptr : get(plan.plainType);
    if (!plan.plainType.isEmpty()) {
        if (!pr || pr->status == ReadResult::Failed)
            return fail("the text was not read");
        if (pr->status == ReadResult::OverCap)
            return fail("the text is over its limit");
        if (!decodePlain(plan.plainType, pr->data, &plain))
            return fail("the text is not valid UTF-8");
    }
    QList<Part> parts;
    if (plan.kind == Kind::Text) {
        for (const QByteArray &type : {plan.htmlType, plan.rtfType}) {
            if (type.isEmpty())
                continue;
            const ReadResult *r = get(type);
            if (r && r->status == ReadResult::Ok && !r->data.isEmpty())
                parts << Part{normalizeType(type), r->data};
        }
    }
    if (plan.plainType.isEmpty()) {
        const ReadResult *hr = get(plan.htmlType);
        if (!hr || hr->status != ReadResult::Ok)
            return fail("the HTML was not read");
        bool ok = false;
        plain = stripHtml(hr->data, &ok);
        if (!ok)
            return fail("the HTML is not valid UTF-8 or UTF-16");
        if (plain.toUtf8().size() > kPlainCap)
            return fail("the text is over its limit");
    }
    if (plain.trimmed().isEmpty())
        return fail("the text is blank");
    Item &it = b.item;
    it.kind = Kind::Text;
    it.plain = plain;
    it.parts = parts;
    it.title = titleOf(plain);
    it.excerpt = excerptOf(plain);
    it.hash = hashOf(Kind::Text, plain.toUtf8());
    b.ok = true;
    return b;
}

QList<QByteArray> plainTypes()
{
    return {"text/plain;charset=utf-8", "UTF8_STRING", "text/plain", "STRING", "TEXT"};
}

QByteArray servePlain(const QString &text, const QByteArray &type)
{
    return isLatin1Type(type) ? text.toLatin1() : text.toUtf8();
}

QByteArray uriList(const QStringList &paths)
{
    QByteArray out;
    for (const QString &p : paths)
        out += QUrl::fromLocalFile(p).toEncoded() + "\r\n";
    return out;
}

QByteArray gnomeCopiedFiles(const QStringList &paths)
{
    QByteArray out = "copy";
    for (const QString &p : paths)
        out += "\n" + QUrl::fromLocalFile(p).toEncoded();
    return out;
}

qint64 ageMs(const Item &item, qint64 nowWallMs, qint64 nowBootMs, const QByteArray &bootId)
{
    const qint64 wall = nowWallMs - item.copiedAtMs;
    if (!bootId.isEmpty() && item.bootId == bootId)
        return std::max(wall, nowBootMs - item.bootAtMs);
    return wall;
}

qint64 clampRetention(qint64 ms)
{
    return std::clamp(ms, kMinRetentionMs, kMaxRetentionMs);
}

qint64 writerWaitMs(qint64 elapsedMs)
{
    return std::clamp(kWriterMaxMs - std::max<qint64>(elapsedMs, 0), qint64(0), kWriterIdleMs);
}

// --- Store ----------------------------------------------------------------------------------------------------------------

void indexItem(Item &item)
{
    if (item.searchText.isEmpty())
        item.searchText = searchKey(item.plain + QLatin1Char('\n') + item.title);
}

qint64 Store::historyBytes() const
{
    qint64 n = 0;
    for (const Item &it : m_history)
        n += it.size();
    return n;
}

qint64 Store::pinnedBytes() const
{
    qint64 n = 0;
    for (const Item &it : m_pinned)
        n += it.size();
    return n;
}

void Store::insertHistory(Item item)
{
    item.pinnedAtMs = 0;
    auto at = std::find_if(m_history.begin(), m_history.end(), [&item](const Item &other) { return other.copiedAtMs <= item.copiedAtMs; });
    m_history.insert(at, std::move(item));
}

QList<QByteArray> Store::enforceHistoryLimits()
{
    QList<QByteArray> out;
    qint64 bytes = historyBytes();
    while (!m_history.isEmpty() && (m_history.size() > kHistoryItems || bytes > kHistoryBytes)) {
        bytes -= m_history.last().size();
        out << m_history.last().id;
        m_history.removeLast();
    }
    return out;
}

Store::AddResult Store::add(Item item)
{
    AddResult r;
    for (const Item &p : std::as_const(m_pinned)) {
        if (p.kind == item.kind && p.hash == item.hash) {
            r.id = p.id;
            return r;
        }
    }
    for (qsizetype i = 0; i < m_history.size(); ++i) {
        if (m_history.at(i).kind == item.kind && m_history.at(i).hash == item.hash) {
            Item same = m_history.takeAt(i);
            same.copiedAtMs = item.copiedAtMs;
            same.bootAtMs = item.bootAtMs;
            same.bootId = item.bootId;
            same.app = item.app;
            r.id = same.id;
            insertHistory(std::move(same));
            r.evicted = enforceHistoryLimits();
            return r;
        }
    }
    r.id = item.id;
    r.added = true;
    indexItem(item);
    insertHistory(std::move(item));
    r.evicted = enforceHistoryLimits();
    return r;
}

Store::PinResult Store::pin(const QByteArray &id, qint64 nowMs)
{
    for (const Item &p : std::as_const(m_pinned))
        if (p.id == id)
            return PinResult::AlreadyPinned;
    for (qsizetype i = 0; i < m_history.size(); ++i) {
        if (m_history.at(i).id != id)
            continue;
        if (m_pinned.size() >= kPinnedItems || pinnedBytes() + m_history.at(i).size() > kPinnedBytes)
            return PinResult::Full;
        Item it = m_history.takeAt(i);
        it.pinnedAtMs = std::max<qint64>(nowMs, 1);
        m_pinned.prepend(std::move(it));
        return PinResult::Pinned;
    }
    return PinResult::NotFound;
}

QList<QByteArray> Store::unpin(const QByteArray &id, bool *found)
{
    *found = false;
    for (qsizetype i = 0; i < m_pinned.size(); ++i) {
        if (m_pinned.at(i).id != id)
            continue;
        *found = true;
        insertHistory(m_pinned.takeAt(i));
        return enforceHistoryLimits();
    }
    return {};
}

bool Store::remove(const QByteArray &id)
{
    for (QList<Item> *list : {&m_pinned, &m_history}) {
        for (qsizetype i = 0; i < list->size(); ++i) {
            if (list->at(i).id == id) {
                list->removeAt(i);
                return true;
            }
        }
    }
    return false;
}

QList<QByteArray> Store::clearHistory()
{
    QList<QByteArray> out;
    for (const Item &it : std::as_const(m_history))
        out << it.id;
    m_history.clear();
    return out;
}

QList<QByteArray> Store::clearPinned()
{
    QList<QByteArray> out;
    for (const Item &it : std::as_const(m_pinned))
        out << it.id;
    m_pinned.clear();
    return out;
}

QList<QByteArray> Store::expire(qint64 nowWallMs, qint64 nowBootMs, const QByteArray &bootId, qint64 retentionMs)
{
    QList<QByteArray> out;
    const qint64 keep = clampRetention(retentionMs);
    for (qsizetype i = m_history.size() - 1; i >= 0; --i) {
        const qint64 age = ageMs(m_history.at(i), nowWallMs, nowBootMs, bootId);
        if (age < 0 || age > keep) {
            out << m_history.at(i).id;
            m_history.removeAt(i);
        }
    }
    return out;
}

bool Store::touch(const QByteArray &id, qint64 copiedAtMs, qint64 bootAtMs, const QByteArray &bootId)
{
    for (qsizetype i = 0; i < m_history.size(); ++i) {
        if (m_history.at(i).id != id)
            continue;
        Item it = m_history.takeAt(i);
        it.copiedAtMs = copiedAtMs;
        it.bootAtMs = bootAtMs;
        it.bootId = bootId;
        insertHistory(std::move(it));
        return true;
    }
    return false;
}

QList<QByteArray> Store::search(const QString &query) const
{
    const QString key = searchKey(query.trimmed());
    QList<QByteArray> out;
    for (const QList<Item> *list : {&m_pinned, &m_history}) {
        for (const Item &it : *list) {
            if (key.isEmpty() || it.searchText.contains(key))
                out << it.id;
        }
    }
    return out;
}

const Item *Store::find(const QByteArray &id) const
{
    for (const QList<Item> *list : {&m_pinned, &m_history})
        for (const Item &it : *list)
            if (it.id == id)
                return &it;
    return nullptr;
}

QList<const Item *> Store::ordered() const
{
    QList<const Item *> out;
    for (const Item &it : m_pinned)
        out << &it;
    for (const Item &it : m_history)
        out << &it;
    return out;
}

QList<QByteArray> Store::loadPinned(QList<Item> items)
{
    std::stable_sort(items.begin(), items.end(), [](const Item &a, const Item &b) { return a.pinnedAtMs > b.pinnedAtMs; });
    QList<QByteArray> dropped;
    qint64 bytes = 0;
    for (Item &it : items) {
        if (find(it.id) || m_pinned.size() >= kPinnedItems || bytes + it.size() > kPinnedBytes) {
            dropped << it.id;
            continue;
        }
        bytes += it.size();
        indexItem(it);
        it.pinnedAtMs = std::max<qint64>(it.pinnedAtMs, 1);
        m_pinned << std::move(it);
    }
    return dropped;
}

QList<QByteArray> Store::loadHistory(QList<Item> items)
{
    QList<QByteArray> dropped;
    for (Item &it : items) {
        if (find(it.id)) {
            dropped << it.id;
            continue;
        }
        indexItem(it);
        insertHistory(std::move(it));
    }
    return dropped + enforceHistoryLimits();
}

// --- Line protocol --------------------------------------------------------------------------------------------------------

QByteArray escape(const QByteArray &utf8)
{
    QByteArray out;
    out.reserve(utf8.size());
    for (const char c : utf8) {
        switch (c) {
        case '\\':
            out += "\\\\";
            break;
        case '\n':
            out += "\\n";
            break;
        case '\r':
            out += "\\r";
            break;
        case '\x1f':
            out += "\\u";
            break;
        default:
            out += c;
        }
    }
    return out;
}

QByteArray escape(const QString &text)
{
    return escape(text.toUtf8());
}

QByteArray unescape(const QByteArray &field)
{
    QByteArray out;
    out.reserve(field.size());
    for (qsizetype i = 0; i < field.size(); ++i) {
        const char c = field.at(i);
        if (c != '\\' || i + 1 >= field.size()) {
            out += c;
            continue;
        }
        const char n = field.at(++i);
        out += n == 'n' ? '\n' : n == 'r' ? '\r' : n == 'u' ? '\x1f' : n;
    }
    return out;
}

QList<QByteArray> splitLine(const QByteArray &line)
{
    QList<QByteArray> out;
    for (const QByteArray &f : line.split('\x1f'))
        out << unescape(f);
    return out;
}
} // namespace ClipLogic
